const canonical={A:['tenant-a','shop-a'],B:['tenant-b','shop-b'],C:['tenant-c','shop-c']};
return $input.all().map(i=>{
 const f=i.json,expected=canonical[f.shop]||[],scopeOK=f.tenant===expected[0]&&f.store===expected[1];
 let actual='NO_PUBLIC_ANSWER';
 if(!scopeOK||f.verified!==true)actual='BLOCKED';
 else if(f.handoff===true)actual='NO_AI_REPLY';
 else if(f.q==='price')actual='COMMERCE_DELEGATE';
 else if(f.state==='PUBLISHED'&&f.visibility==='PUBLIC'&&f.approved===true&&
   !f.version&&typeof f.text==='string'&&f.text.length>0)actual='ANSWER';
 return {json:{case_id:f.shop+'-'+f.q+'-'+f.expected,actual,expected:f.expected,
   pass:actual===f.expected,tenants_mixed:false,provider_sends:0,orders_written:0,
   paid_model_calls:0,storage_writes:0,source:'SYNTHETIC_FIXTURE_ONLY'}};
});

const a=$input.all().map(x=>x.json);
const invalid=a.filter(x=>!x.pass||x.provider_sends!==0||x.orders_written!==0||
 x.paid_model_calls!==0||x.storage_writes!==0||x.tenants_mixed!==false);
if(invalid.length)throw new Error('V141_FAIL:'+invalid.map(x=>x.case_id).join(','));
return [{json:{suite:'V14_1_THREE_SHOP_KNOWLEDGE_SMOKE',cases:a.length,passed:a.length,
 failed:0,provider_sends:0,orders_written:0,paid_model_calls:0,storage_writes:0,
 real_provider_tested:false,real_customer_data_used:false,
 real_knowledge_source_tested:false,production_ready:false}}];
